(function(){
  'use strict';
  const G=window.StudioGame, P=window.StudioPeople, $=id=>document.getElementById(id);
  const SAVE='loop_studio_run_v4', META='loop_studio_meta_v1';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const yen=n=>'¥'+Math.round(n).toLocaleString('zh-CN');
  const pct=(n,d)=>Math.max(0,Math.min(100,Math.floor(n/d*100)));
  let run=null,meta=G.emptyMeta(),view='home',tab='work',hiddenPrompt=false,setupGenre='story',toastTimer,storageOK=true;
  try{const m=JSON.parse(localStorage.getItem(META)||'null');if(m&&m.version===1&&Number.isFinite(m.exp)&&m.exp>=0&&m.receipts&&typeof m.receipts==='object'&&Array.isArray(m.history))meta=m;const s=JSON.parse(localStorage.getItem(SAVE)||'null');if(G.validateRun(s))run=s;}catch{}
  const audio=window.DSHAudio.create(window);audio.init(updateAudio);
  function updateAudio(){const a=audio.getState();const muted=a.settings?.muted??a.muted;const b=$('audio-toggle');b.classList.toggle('on',!muted);b.setAttribute('aria-label',muted?'开启声音':'关闭声音');b.title=muted?'开启声音':'关闭声音';}
  function save(){try{if(run)localStorage.setItem(SAVE,JSON.stringify(run));localStorage.setItem(META,JSON.stringify(meta));}catch{if(storageOK){storageOK=false;toast('浏览器未允许保存，当前进度仅在本次打开期间保留。');}}}
  function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('toast');toastTimer=setTimeout(()=>$('toast').classList.remove('toast'),3200);}
  function disabled(ok){return ok?'':' disabled';}
  function busy(){return !run||run.over||run.pendingEvent||run.pendingCards;}
  function bar(value,max,color){return `<div class="progress" style="--bar:${color||'var(--teal)'}"><span style="width:${pct(value,max)}%"></span></div>`;}
  function title(eye,name,sub,right=''){return `<div class="title-row"><div><div class="eyebrow">${eye}</div><h1>${name}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</div>`;}
  function officeSVG(){
    const people=run?G.teamSize(run):2;
    const desks=[{x:156,y:170,c:'#92bca8'},{x:268,y:170,c:'#a6afe0'},{x:213,y:239,c:'#d8bb80'},{x:325,y:239,c:'#d8a991'}];
    return `<svg class="office-art" viewBox="0 0 530 350" aria-label="像素风工作室，团队在温暖灯光下制作游戏" role="img"><defs><pattern id="floor" width="38" height="38" patternUnits="userSpaceOnUse" patternTransform="matrix(1 .5 -1 .5 0 0)"><rect width="38" height="38" fill="#384a43"/><path d="M0 0h38v38" fill="none" stroke="#4a5a4f" stroke-width="1"/></pattern><linearGradient id="windowlight" x2="0" y2="1"><stop stop-color="#a1c6ae"/><stop offset="1" stop-color="#6d9c91"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="6"/></filter></defs><ellipse cx="283" cy="276" rx="185" ry="52" fill="#0f191c" opacity=".3"/><path d="M76 169 276 68 466 163 267 268Z" fill="#263932"/><path d="M76 169v48l191 98v-47Z" fill="#26352f"/><path d="M267 268v47l199-100v-52Z" fill="#1c2e2b"/><path d="M76 169 276 68 466 163 267 268Z" fill="url(#floor)"/><path d="M76 169V72L276-27v95Z" fill="#506258" transform="translate(0 24)"/><path d="M276 92V-3l190 95v95Z" fill="#344c46"/><path d="M99 105 190 60v58l-91 45Z" fill="#253d39" stroke="#72887b" stroke-width="4"/><path d="M105 106 184 67v48l-79 39Z" fill="url(#windowlight)"/><path d="M144 87v48M106 129l77-39" stroke="#3e5c50" stroke-width="4"/><path d="M107 128 113 110l8-4 2 10 9-20 9-5 3 24 11-23 12-6 8 14 8-4v18l-78 39Z" fill="#42665a" opacity=".55"/><path d="M147 142 270 203 334 171 188 115Z" fill="#e4d5a9" opacity=".065"/><path d="m219 53 33-16v29l-33 17Z" fill="#c7b794"/><path d="m225 56 20-10v16l-20 10Z" fill="#718b72"/><path d="M304 49 358 76v42l-54-27Z" fill="#233d37" stroke="#789082" stroke-width="2"/><path d="m313 65 34 17m-34-7 25 13m-25-3 30 15" stroke="#b0b68e" stroke-width="2"/><path d="m386 99 55 28v8l-55-28Z" fill="#a18a65"/><path d="m390 92 5 2v10l-5-2m9-3 5 2v8l-5-2m10-2 5 2v8l-5-2m8-3 5 2v9l-5-2" fill="#91ab96" stroke="#6d8a77" stroke-width="2"/>
    <g transform="translate(90 174)"><path d="m0 0 21-10 17 8-20 10Z" fill="#bc9a6a"/><path d="M0 0v18l18 10V8m0 20 20-10V-2" fill="#6b6044"/><path d="M18-5v-38" stroke="#547d64" stroke-width="4"/><path d="M18-16C-8-18-8-35 1-31c13 2 15 8 17 15m0-5c23-6 26-22 17-21-15 0-19 12-17 21m0-9c-14-9-13-23-7-21 10 2 11 13 7 21" fill="#739b78"/></g>
    ${desks.map((d,i)=>`<g transform="translate(${d.x} ${d.y})"><path d="m-25 0 49-25L72-1 23 24Z" fill="#b2966b" stroke="#ccb184" stroke-width="1"/><path d="M-25 0v6l48 25v-7m49-25v7L23 31v-7" fill="#73684f"/><path d="M-19 9v27m79-24v26M22 31v24" stroke="#374039" stroke-width="5"/><path d="m0-11 29-15v24L0 13Z" fill="#1b2b30" stroke="#667f76" stroke-width="2"/><path d="m3-10 23-12v18L3 8Z" fill="${run?.team?.[i]?.color||d.c}" opacity=".65"/><path d="m6-10 8-4m-8 9 15-8m-15 13 10-5" stroke="#d7e0c9" stroke-width="1" opacity=".6"/><path d="m13 13 12-6 12 6-12 6Z" fill="#566c60"/><path d="m29 8 17-8 12 6-17 8Z" fill="#aeb8a0"/><path d="m54-7 6-3v9l-6 3Z" fill="#d5c3a1"/>${i<people?`<g><path d="M8 37v15l13 7 12-7V39" fill="#26363a"/><path d="m8 34 13-7 13 7-13 7Z" fill="#526b61"/><path d="M12 23v17l10 6 9-5V23" fill="${d.c}"/><path d="m12 22 10-5 9 5v10l-9 5-10-5Z" fill="#d6ad87"/><path d="m10 19 11-6 12 6v7l-5-2-1-5-13 6-4-1Z" fill="${i%2?'#76624a':'#3c3c34'}"/><path d="m15 42-9-8m22 9 9-9" stroke="${d.c}" stroke-width="5"/></g>`:''}</g>`).join('')}
    <path d="m407 178 27-14 15 8-27 14Z" fill="#9d8c68"/><path d="M407 178v32l15 8v-32m27-14v32l-27 14v-32" fill="#526252"/><path d="m415 181 10-5 8 4-10 5Z" fill="#b7ba9e"/><path d="m396 155 6-3v18l-6 3Z" fill="#d9c198"/><path d="m384 150 16-20 17 20-17 8Z" fill="#dac28c"/><ellipse cx="401" cy="151" rx="15" ry="5" fill="#f5d795" opacity=".22" filter="url(#glow)"/></svg>`;
  }
  function home(){const live=run&&!run.over;return title('MAKE SOMETHING WORTH PLAYING','每一周，离好游戏更近一步。','一间小工作室，一个新点子，还有属于你的制作人故事。')+
    `<section class="hero"><div class="hero-copy"><div class="eyebrow">下一个好点子 · 等你开工</div><h1>从一个点子，<br>到一款真正的游戏。</h1><p>安排团队，探索技术蓝图，应对开发中的意外。<br>时间没有终点，预算会提醒你何时该发售。</p><div class="hero-buttons"><button class="btn-primary" data-action="${live?'continue':'setup'}">${live?'继续开发「'+esc(run.name)+'」':'＋ 立项，开始第一款游戏'} <span>↗</span></button>${live?'<button class="btn-ghost" data-action="setup">新项目</button>':'<button class="btn-ghost" data-action="help">了解怎么玩 →</button>'}</div><p class="hero-note">回合开发 · 每周随机事件 · 技术构筑 · 局外成长</p></div><div class="home-office">${officeSVG()}</div></section>
    <div class="section-heading"><h2>这一次，你想做什么？</h2><small>三种项目方向，各有不同的开发重点</small></div><div class="genre-grid">${G.GENRES.map((g,i)=>`<article class="genre-card" style="--accent:${['#d8b879','#80b4cf','#b29bce'][i]}"><div class="genre-icon">${g.icon}</div><h3>${g.name}</h3><div class="genre-meta">${g.tag}</div><p>${g.desc}</p><button data-action="setup" data-genre="${g.id}">选择这个方向 <span>↗</span></button></article>`).join('')}</div>
    <div class="home-bottom"><div class="home-tip"><span>◷</span><div><h3>开发多久，由你决定</h3><p>没有固定回合上限。团队、项目范围与技术债决定每周成本。</p></div></div><div class="home-tip"><span>◇</span><div><h3>每一作，都是新的开始</h3><p>完成作品获得经验，解锁技术蓝图与下一局的开局加成。</p></div></div></div>`;
  }
  function game(){if(!run)return title('YOUR NEXT PROJECT','工作室还没有项目','从你和阿策两个人开始，安排 13 项开发工作。')+'<section class="panel empty"><h2>从第一周，开始你的作品。</h2><button data-action="setup" class="btn-primary">＋ 开始一个新项目</button></section>';
    const s=run,c=G.cost(s),p=G.preview(s),active=!busy(),g=G.GENRES.find(g=>g.id===s.genre),f=G.forecast(s);
    let html=title('PROJECT WORKBENCH',esc(s.name),`${g.name} · 五类工作 / 十三项行动`, `<div class="title-badges"><span class="pill gold">第 ${s.week} 周</span><span class="pill">${s.over?'项目已结束':G.canRelease(s)?'可以正式发售':'开发中'}</span></div>`);
    if(s.over)html+='<div class="notice">'+(s.result.released?'作品已经发售，真实评级已揭晓。':'项目已终止，制作经验已结算。')+' <button class="btn-small" data-action="result">查看结算</button> <button class="btn-small" data-action="setup">下一款作品 ↗</button></div>';
    if(!s.over&&s.money<c.total)html+='<div class="notice">预算不足以推进下一周。可减少买量预算、融资，或完成上架后发售。<button class="btn-small" data-action="abort">终止项目</button></div>';
    html+=`<div class="stats"><div class="stat"><div class="label">项目资金</div><div class="value gold num">${yen(s.money)}</div><div class="note">累计投入 ${yen(s.spent)}</div></div><div class="stat"><div class="label">预计可维持</div><div class="value teal num">${Math.floor(s.money/c.total)}<small>周</small></div><div class="note">没有固定回合上限</div></div><div class="stat"><div class="label">本周总支出</div><div class="value num">${yen(c.total)}</div><div class="note">工资 ${yen(c.wages)} / 维护与工具 ${yen(c.overhead+c.tools)} / 买量 ${yen(c.ads)}</div></div><div class="stat"><div class="label">工作室伙伴</div><div class="value num">${G.teamSize(s)}<small>/ 8 人</small></div><div class="note">士气 ${Math.round(s.morale)} · 技术债 ${Math.round(s.debt)}</div></div></div>`;
    html+=strategyPanel(s,p);
    if(G.availableRecruits(s).length&&!s.over)html+=`<div class="notice recruit-notice"><span>✉ ${G.availableRecruits(s).map(m=>esc(m.name)).join('、')}发来伙伴来信。</span><button class="btn-small" data-action="tab" data-tab="team">查看人物卡 ↗</button></div>`;
    html+=`<div class="tabs" role="tablist">${[['work','开发现场'],['team','团队人物 '+G.teamSize(s)],['features','功能与蓝图'],['logs','开发记录']].map(([id,n])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="tab" data-tab="${id}">${n}</button>`).join('')}</div>`;
    if(tab==='team')return html+P.roster(s,active);if(tab==='features')return html+features();if(tab==='logs')return html+logs();
    html+=P.strip(s,active);
    html+=`<div class="ratings-summary" aria-label="作品评级概览">${G.GROUPS.map(g=>g.id==='release'?`<a href="#group-release" class="rating-summary-item"><small>能否上架</small><strong class="${G.complete(s)?'teal':''}">${G.complete(s)?'可上架':'未就绪'}</strong><span>两项工作均须完成</span></a>`:ratingTile(s,g)).join('')}</div>`;
    html+=`<div class="development-layout"><div class="work-groups">${G.GROUPS.map(g=>workGroup(s,g,p,active)).join('')}</div><aside class="project-aside"><section class="panel"><div class="panel-head"><h2>发售准备</h2><span class="pill">${G.goals(s).filter(g=>g.ok).length} / 2</span></div><div class="panel-body"><div class="goal-list">${G.goals(s).map(g=>`<div class="goal ${g.ok?'done':''}"><span>${g.ok?'✓':'·'}</span><span>${g.name}</span><span>${g.value}</span></div>`).join('')}</div><p class="quality-note">上架两项均到 100% 才能发售。内容、程序、商业化和宣发决定品质与收益，可自行取舍投入。</p><button class="btn-teal release-btn" data-action="release"${disabled(G.canRelease(s))}>${G.canRelease(s)?'正式发售这款游戏 ↗':'完成上架后即可发售'}</button><div class="financial"><div>综合评级认知<strong>${esc(f.rating.text)}</strong></div><div>当前版本收入区间<strong>${yen(f.low)}—${yen(f.high)}</strong></div></div><p class="quality-note">区间来自当前认知，已扣发行分成；宣传越少，估算越宽。未计后续开发成本，发售时揭晓真实评级。</p></div></section>${eventPanel(s)}<section class="panel"><div class="panel-head"><h2>团队与资金</h2></div><div class="panel-body"><p class="quality-note">每人每周专注一项工作。邀请伙伴花 ¥180，暂别花 ¥100，均占本周管理行动。完成原型、切片和完整内容后结识新伙伴。</p><button class="btn-small" data-action="tab" data-tab="team">查看伙伴来信</button><div class="funding"><div><b>发行合作 · ¥2,200</b><p>${s.funding?'已合作，发售收入分成 22%':'核心平均进度 30% 可签，收入分成 22%'}</p></div><button class="btn-small" data-action="funding"${disabled(active&&!s.funding&&G.coreProgress(s)>=.3)}>${s.funding?'已签订':'了解合作'}</button></div></div></section><section class="panel"><div class="panel-head"><h2>技术蓝图</h2><small>${s.cards.length} 张</small></div><div class="panel-body"><div class="pill-list">${s.cards.map(id=>`<span class="pill gold">◇ ${G.CARDS.find(c=>c.id===id).name}</span>`).join('')||'<p class="quality-note">保持轻量开发</p>'}</div></div></section></aside></div>`;
    return html;
  }
  function strategyPanel(s,p){const o=G.objectiveStatus(s,s.over&&s.result.released?s.result:undefined),f=G.forecast(s);return `<section class="strategy-panel"><div class="strategy-title"><div><span class="eyebrow">BUILD · LEARN · DECIDE</span><h2>${o.name} <span class="pill dim">${s.over?s.result.objectiveOK?'已达成':'未达成':o.ok?'有望达成':'开发中'}</span></h2><p>${s.objective==='acclaim'?'综合真实评级达到 A-':'发售后项目结余至少 ¥1,200'} · 达成额外 +40 EXP</p></div><div class="objective-value gold">${s.over&&s.result.released?s.objective==='acclaim'?s.result.rating:yen(s.result.profit):s.objective==='acclaim'?esc(f.rating.text):yen(f.low+s.income-s.spent)+'—'+yen(f.high+s.income-s.spent)}<small>${s.over?'实际结算':'基于当前认知，未计未来成本'}</small></div></div><div class="strategy-flow"><span>推进工作</span><b>→</b><span>积累真实品质</span><b>→</b><span>宣传验证认知</span><b>→</b><span>决定投放与发售</span></div><p class="quality-note">????? 表示完全未知；例如 B???? 是可能偏离真实值的初步判断。问号越少，误差越小。宣传改变认知，不会直接提高作品品质。</p></section>`;}
  function job(s,j,p,active){const assigned=s.team.filter(m=>m.job===j.id),gain=p?p.gains[j.id]:0,done=G.progress(s,j.id)>=1,blockedWork=G.workLimit(s,j.id)<=s.work[j.id]&&!done;return `<div class="job work-item ${s.focus===j.id?'focus':''}" data-work="${j.id}" style="--job-color:${j.color}"><div class="job-line"><div class="job-name"><strong>${j.name}</strong><small>${j.desc}</small></div><button class="focus-btn ${s.focus===j.id?'selected':''}" data-action="focus" data-job="${j.id}"${disabled(active)}>${s.focus===j.id?'✦ 主攻':'设为主攻'}</button></div><div class="progress-label"><span>${Math.floor(s.work[j.id])} / ${s.req[j.id]} 工作量</span><b>${pct(s.work[j.id],s.req[j.id])}%${!done&&p?' · 本周 +'+Math.round(gain):done?' · 已完成':''}</b></div>${bar(s.work[j.id],s.req[j.id],j.color)}<div class="job-members">${assigned.map(m=>`<span style="color:${m.color}">${esc(m.name)} · ${G.taskSkill(m,j.id)}%${m.job!==m.lastJob?' · 磨合中':''}</span>`).join(' / ')||'未安排伙伴'}${blockedWork?'<span class="red"> · 等待上游工作</span>':''}${j.id==='acquisition'&&s.adBudget===0?'<span> · 预算为 ¥0，暂停买量</span>':''}</div>${done&&['systems','qa','acquisition'].includes(j.id)?'<p class="ops-note">'+(j.id==='systems'?'继续工作可偿还技术债。':j.id==='qa'?'继续工作可修复问题。':'继续工作仍会按本周预算追加投放。')+'</p>':''}</div>`;}
  function ratingTile(s,g){const v=G.ratingView(s,g.id);return `<a href="#group-${g.id}" class="rating-summary-item" style="--rating-color:${g.color}"><small>${g.rating}</small><strong class="rating-text" data-rating="${g.id}">${esc(v.text)}</strong><span>${v.exact?'真实评级已揭示':v.level?'认知范围 '+v.lowGrade+'—'+v.highGrade:'未获得玩家反馈'}</span></a>`;}
  function workGroup(s,g,p,active){const v=g.id==='release'?null:G.ratingView(s,g.id),list=G.JOBS.filter(j=>j.group===g.id);return `<section class="panel work-group" id="group-${g.id}" style="--group-color:${g.color}"><header class="work-group-head"><div><span class="eyebrow">${String(G.GROUPS.indexOf(g)+1).padStart(2,'0')} / ${g.id==='release'?'必须完成':'可自主取舍'}</span><h2>${g.icon} ${g.name}</h2></div><div class="group-verdict"><small>${g.rating}</small><strong>${v?esc(v.text):G.complete(s)?'可上架':'未就绪'}</strong>${v?`<span>${v.exact?'真实评级':v.level?'范围 '+v.lowGrade+'—'+v.highGrade:'等待反馈'}</span>`:`<span>上架总进度 ${Math.floor(G.groupProgress(s,'release')*100)}%</span>`}</div></header>${list.map(j=>job(s,j,p,active)).join('')}${g.id==='promotion'?marketing(s,active):g.id==='content'?`<div class="group-note"><span>${s.designLocked?'范围已冻结：程序 / 美术 +12%，不能扩功能。':'内容平均达 60% 可冻结范围，程序 / 美术 +12%。'}</span><button class="btn-small" data-action="freeze"${disabled(active&&!s.managed&&G.groupProgress(s,'content')>=.6&&(!s.designLocked||s.money>=180))}>${s.designLocked?'解冻 · ¥180':'冻结范围'}</button></div>`:g.id==='release'?'<p class="group-note">资料准备 100% 后才能推进审核。上架资格确定，不受评级随机值影响。</p>':''}</section>`;}
  function marketing(s,active){const a=G.adProjection(s),level=G.revealLevel(s);return `<div class="marketing-controls"><div class="reveal-progress"><strong>评级揭示 ${level} / 5</strong><span>宣传 0 / 1 / 25 / 50 / 75 / 100% 逐步缩小误差</span></div><p class="quality-note">宣传和买量都不影响发售资格。买量需要安排伙伴，并设置本周预算；未安排人手不扣投放费，¥0 暂停。</p><label class="field"><span>本周买量预算</span><select id="ad-budget" aria-label="本周买量预算"${disabled(active)}>${G.AD_BUDGETS.map(n=>`<option value="${n}"${s.adBudget===n?' selected':''}>${n===0?'暂停买量 · ¥0':yen(n)+' / 周'}</option>`).join('')}</select></label><div class="ad-ledger"><div><span>累计买量投入</span><b>${yen(a.spend)}</b></div><div><span>当前认知下净回款区间</span><b>${yen(a.low)}—${yen(a.high)}</b></div><div><span>预算转化比例（已扣分成）</span><b>${Math.round(a.lowRate*100)}%—${Math.round(a.highRate*100)}%</b></div></div><p class="quality-note">回款在发售时结算，按当时的综合真实评级：内容 40% / 完善度 30% / 商业化 20% / 推广 10%。C、D 档回款低于投入，B 档起有回本机会；发行分成会降低回款。评级未知时，区间很宽。</p></div>`;}
  function eventPanel(s){const pending=G.event(s);const last=s.logs.find(x=>x.text.includes('：')&&!x.text.startsWith('完成第')&&!x.text.startsWith('采用技术')&&!x.text.startsWith('扩展功能'));
    return `<section class="panel event-empty"><div class="event-eyebrow"><span>✧ ${pending?'本周事件 · 等待决定':'开发中的小插曲'}</span><span>${pending?'待处理':'每周 1 次'}</span></div><h3>${pending?pending.title:s.week===1?'故事，从第一周开始。':'每一步，都有新的可能。'}</h3><p>${pending?pending.text:s.week===1?'安排好伙伴的岗位，选一个本周主攻方向。推进一周后，会发生属于这个项目的随机事件。':'灵感、意外、合作与团队日常，都会影响这款作品的诞生。事件与开发状态有关。'}</p>${pending?'<button class="btn-teal btn-small" style="margin-top:16px" data-action="prompt">处理这个事件 →</button>':last?`<div class="event-last">最近记录 · ${esc(last.text)}</div>`:''}</section>`;
  }
  function features(){const s=run,active=!busy();return `<p class="legend">功能与题材的契合会影响收入与内容评级基础。越晚加入，返工越多；每项功能持续增加 ¥22/周维护。冻结范围后不能增删。</p><section class="panel">${G.FEATURES.map(f=>{const owned=s.features.includes(f.id),p=G.featurePreview(s,f.id),req=owned?s.featureWork[f.id]:p.req;return `<div class="feature-row"><div><h3>${owned?'✓ ':''}${f.name} <span class="pill ${p.fit>=1.1?'gold':'dim'}">${p.fit>=1.1?'题材契合':p.fit<.9?'方向偏离':'通用功能'}</span></h3><p>${f.desc} · 内容评级基础 +${((f.play+f.visual)*p.fit*.13).toFixed(1)}</p><small>${Object.entries(req).map(([k,v])=>G.JOBS.find(j=>j.id===k).short+' +'+v).join(' · ')}<br>技术债 +${p.debt} · 维护 +22/周${!owned?' · 当前返工 +'+p.rework+'%':''}</small></div><button class="${owned?'btn-ghost':'btn-teal'}" data-action="${owned?'cut':'feature'}" data-id="${f.id}"${disabled(active&&!s.managed&&!s.designLocked&&(owned||s.money>=f.cost))}>${owned?'删减功能':'+ 加入 '+yen(f.cost)}</button></div>`;}).join('')}</section><div class="section-heading"><h2>本项目的技术路线</h2><small>蓝图可以放弃，收益与代价一并保留</small></div><div class="tool-grid">${s.cards.map(id=>card(G.CARDS.find(c=>c.id===id),false,true)).join('')||'<p class="legend">轻量开发 · 没有采用蓝图</p>'}</div>`;}

  function logs(){return `<section class="panel"><div class="panel-head"><h2>开发记录</h2><small>记录认知与实际行动</small></div><div class="panel-body"><div class="dev-logs">${run.logs.map(l=>`<p><span>W${l.week}</span> ${esc(l.text)}</p>`).join('')}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>每周账本</h2></div><div class="ledger-wrap"><table class="ledger"><thead><tr><th>周次</th><th>总支出</th><th>其中买量</th><th>剩余资金</th><th>伙伴分工</th></tr></thead><tbody>${run.history.slice().reverse().map(h=>`<tr><td>${h.week}</td><td>${yen(h.cost)}</td><td>${yen(h.ads)}</td><td>${yen(h.money)}</td><td>${h.team.filter(m=>m.output>0).map(m=>esc(m.name)+' · '+G.JOBS.find(j=>j.id===m.job).name).join(' / ')}</td></tr>`).join('')||'<tr><td colspan="5">推进第一周后记录收支。</td></tr>'}</tbody></table></div></section>`;}
  function card(c,locked,owned){return `<article class="tool-card ${locked?'locked':''}"><div class="tag">◇ ${c.tag}蓝图</div><h3>${c.name}</h3><p>${c.desc}</p><div class="card-bottom"><span>${locked?'制作经验达到 '+c.unlock+' 解锁':'已加入随机蓝图池'}</span><span class="${owned?'teal':'muted'}">${owned?'本局已采用 ✓':locked?'未解锁':'已开放'}</span></div></article>`;}
  function blueprints(){return title('THE TOOLBOX','每一张蓝图，一种开发思路。','开局与开发里程碑提供三选一。随机组合，形成你的制作方法。',`<span class="pill gold">${G.CARDS.filter(c=>c.unlock<=meta.exp).length} / ${G.CARDS.length} 已开放</span>`)+`<div class="tool-grid">${G.CARDS.map(c=>card(c,c.unlock>meta.exp,run&&run.cards.includes(c.id))).join('')}</div>`;}
  function career(){const released=meta.history.filter(h=>h.released),best=Math.max(0,...released.map(h=>h.score));return title('THE PRODUCER JOURNAL','作品会结束，经验会留下。','每一次尝试，都让下一款游戏多一点可能。')+`<div class="career-summary"><div class="stat"><span class="label">累计制作经验</span><div class="value gold">${meta.exp}</div><span class="note">每局仅结算一次</span></div><div class="stat"><span class="label">已发售作品</span><div class="value teal">${released.length}<small>款</small></div><span class="note">共经历 ${meta.history.length} 个项目</span></div><div class="stat"><span class="label">最高作品评分</span><div class="value">${best||'—'}</div><span class="note">开局加成额度 ${G.capacity(meta)} 点</span></div></div><section class="panel"><div class="panel-head"><h2>下一局的准备</h2><small>累计解锁，不扣除经验</small></div><div class="panel-body"><div class="unlock-list">${G.BUFFS.map(b=>`<div class="unlock ${b.unlock>meta.exp?'locked':''}"><span>${b.unlock>meta.exp?b.unlock+' 经验':'已解锁'}</span><strong>${b.name}</strong><p>${b.desc} · 携带 ${b.cost} 点</p></div>`).join('')}<div class="unlock ${meta.exp<260?'locked':''}"><span>${meta.exp<260?'260 经验':'已解锁'}</span><strong>额外携带额度</strong><p>开局加成额度由 2 点提升到 3 点</p></div></div></div></section><div class="section-heading"><h2>你的作品履历</h2><small>名字、成绩与这一路的选择</small></div>${meta.history.length?meta.history.map(h=>`<article class="career-record"><div><h3>${esc(h.name)} <span class="pill ${h.released?'':'dim'}">${h.released?'已发售':'已终止'}</span></h3><p>${G.GENRES.find(g=>g.id===h.genre)?.name||'独立游戏'} · 开发 ${h.weeks} 周 · 成本 ${yen(h.cost)} · ${h.released?'项目结余 '+yen(h.profit):'保留里程碑经验'}</p>${h.team?`<p>制作团队：${h.team.map(m=>esc(m.name)).join("、")}</p>`:""}<p>${h.cards.map(id=>G.CARDS.find(c=>c.id===id)?.name||'').join(' / ')}</p></div><div class="record-score">${h.released?(h.rating||h.score):'—'}<small>制作经验 +${h.exp}</small></div></article>`).join(''):`<section class="panel empty"><div class="empty-icon">↗</div><h2>第一份作品，还在路上。</h2><p>发售作品或终止一个已达成里程碑的项目后，履历会记录在这里。</p><button class="btn-primary" data-action="${run&&!run.over?'continue':'setup'}">${run&&!run.over?'回到开发现场':'开始第一款游戏'}</button></section>`}`;}
  function render(){const labels={home:'工作室大厅',game:'开发现场',blueprints:'技术蓝图',career:'制作人履历'};document.querySelectorAll('.sidebar nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('location').textContent=labels[view];$('run-dot').style.display=run&&!run.over?'':'none';const next=[80,160,260,400].find(n=>n>meta.exp);$('meta-mini').innerHTML=`<div class="side-growth"><small class="muted">制作人经验</small><div style="margin-top:8px"><strong class="gold">${meta.exp}</strong><small class="muted">EXP</small></div>${bar(meta.exp,next||meta.exp||1)}<p style="margin-top:9px">${next?'距离下一解锁还差 '+(next-meta.exp)+' 经验':'全部成长内容已开放'}</p></div>`;
    $('app').innerHTML=({home,game,blueprints,career}[view])();renderFooter();save();if(view==='game'&&!hiddenPrompt&&run&&!run.over){if(run.pendingEvent)showEvent();else if(run.pendingCards)showCards();}}
  function renderFooter(){if(view!=='game'||!run||run.over){$('footer').innerHTML='';return;}const s=run,c=G.cost(s),pending=s.pendingEvent||s.pendingCards;$('footer').innerHTML=`<footer class="actionbar"><div><p><strong>第 ${s.week} 周 · ${G.JOBS.find(j=>j.id===s.focus).name}</strong><span class="break-mobile">　${s.reserve?s.reserve+' 人尚未分配岗位':'岗位调整与主攻切换不消耗时间'}</span></p><p class="${s.money<c.total?'danger-text':''}" style="margin-top:4px">${pending?'完成当前选择后才能继续开发':s.money<c.total?'预算不足，请处理资金或结束项目':'推进后支付 '+yen(c.total)+'，并触发一次随机事件'}</p></div><div class="action-controls"><div class="pace" aria-label="开发节奏">${[['rest','休整'],['normal','正常'],['crunch','赶工']].map(([id,n])=>`<button data-action="pace" data-pace="${id}" title="${id==='rest'?'效率 70%，士气 +12':id==='crunch'?'效率 135%，士气 −10，增加问题与技术债':'标准效率，士气 +1'}" class="${s.pace===id?'selected':''}"${disabled(!busy())}>${n}</button>`).join('')}</div><button data-action="${pending?'prompt':'advance'}" class="btn-primary next-week"${disabled(pending||s.money>=c.total)}>${pending?'完成当前选择':'推进一周'}　→</button></div></footer>`;}
  const dialog=$('dialog');let dialogKind='';
  function showDialog(html,kind){dialogKind=kind;dialog.innerHTML=`<div class="dialog-body">${html}</div>`;if(!dialog.open)dialog.showModal();}
  function close(){dialog.close();dialogKind='';}
  function dialogHeader(eye,name,closable=true){return `<div class="dialog-header"><div><div class="eyebrow">${eye}</div><h2 id="dialog-title">${name}</h2></div>${closable?'<button class="close-btn" data-action="close" aria-label="关闭窗口">×</button>':''}</div>`;}
  function setup(genreId){setupGenre=genreId||setupGenre;const g=G.GENRES.find(g=>g.id===setupGenre);showDialog(dialogHeader('A NEW BEGINNING','立项，开始新的作品。')+`<p class="dialog-desc">你与阿策，两人共同开工。标准启动资金 ${yen(7600)}，没有固定开发期限；伙伴随项目进度出现。</p><form id="setup-form"><div class="setup-genres">${G.GENRES.map(x=>`<button type="button" class="${x.id===setupGenre?'selected':''}" data-action="setup-genre" data-genre="${x.id}">${x.icon} ${x.name}</button>`).join('')}</div><label class="field"><span>作品名称</span><input name="name" maxlength="18" required value="${esc(g.title)}" autocomplete="off"></label><label class="field"><span>这款作品的目标 · 达成额外 +40 EXP</span><select name="objective"><option value="profit">商业回报：项目结余至少 ¥1,200</option><option value="acclaim">口碑佳作：综合真实评级至少 A-</option></select></label>${P.setup()}<div class="radio-line"><label><input type="radio" name="difficulty" value="normal" checked> 标准开发</label><label><input type="radio" name="difficulty" value="hard"> 困难 · 更少资金 / 工资 +15%</label></div><div class="progress-label"><span>开局加成 · 最多 ${G.capacity(meta)} 点</span><b>累计 ${meta.exp} EXP</b></div><div class="buff-options">${G.BUFFS.map((b,i)=>`<label class="buff-option ${b.unlock>meta.exp?'locked':''}"><input type="checkbox" name="buff" value="${b.id}" ${i<2?'checked':''} ${b.unlock>meta.exp?'disabled':''}><span><strong>${b.name} · ${b.cost} 点</strong><small>${b.desc}${b.unlock>meta.exp?' / '+b.unlock+' 经验解锁':''}</small></span></label>`).join('')}</div><details style="margin-top:17px;font-size:10px;color:var(--muted)"><summary>固定种子（可选，用于重玩同一组随机选择）</summary><label class="field" style="margin-top:10px;margin-bottom:0"><input name="seed" type="number" min="1" max="4294967295" placeholder="留空则随机生成"></label></details>${run&&!run.over?'<p class="warning-note">开始新项目会结束当前项目，并结算已有里程碑经验。请先确认当前进度。</p>':''}<div id="setup-error" class="warning-note" role="alert"></div><div class="dialog-actions"><button type="button" class="btn-ghost" data-action="close">再想想</button><button class="btn-primary" type="submit">开始本次开发 →</button></div></form>`,'setup');}
  function showCards(){hiddenPrompt=false;showDialog(dialogHeader('CHOOSE YOUR APPROACH',run.cards.length?'新的阶段，新的可能。':'选择你的第一张技术蓝图。')+`<p class="dialog-desc">选中的蓝图立即生效，持续整个项目。每张蓝图都有收益与代价，可按预算与目标决定是否采用。</p><div class="blueprint-choices">${run.pendingCards.map(id=>{const c=G.CARDS.find(x=>x.id===id);return `<button class="blueprint-choice" data-action="card" data-id="${id}"><span class="card-symbol">◇</span><strong>${c.name}</strong><small>${c.desc}</small><span class="pick">采用这张蓝图 ↗</span></button>`;}).join('')}</div><div class="dialog-actions"><button class="btn-ghost" data-action="card" data-id="skip">放弃本轮，保持轻量</button></div><p class="quality-note">关闭可先检查预算，再从底栏返回选择。</p>`,'cards');}
  function showEvent(){const e=G.event(run);hiddenPrompt=false;showDialog(dialogHeader('WEEK '+String(run.week-1).padStart(2,'0')+' · '+e.tag,e.title)+`<div class="event-image" aria-hidden="true">${{inspiration:'✦',palette:'◈',coffee:'☕',backup:'▣',forms:'▤',feedback:'✉',bug:'⌘',showcase:'✧',scope:'◇',tired:'☾',break:'♧',discount:'◉',compat:'⌘',debt:'⌘'}[e.id]||'✦'}</div>${P.voice(run,e)}<p class="dialog-desc">${e.text}</p><div class="event-options">${e.choices.map((c,i)=>`<button class="event-option" data-action="event" data-index="${i}"${disabled(G.eventChoiceStatus(run,i).ok)}><div><strong>${c.label}</strong><small>${c.hint}${!G.eventChoiceStatus(run,i).ok?' · '+G.eventChoiceStatus(run,i).reason:''}</small></div><span>↗</span></button>`).join('')}</div><p class="quality-note">你的决定会自动保存。同一开发周只发生一次事件。</p>`,'event');}
  function result(){const r=run.result;showDialog(dialogHeader('THE TRUTH BEHIND THE QUESTION MARKS',r.released?'「'+esc(r.name)+'」发售了。':'把经验，留给下一作。')+`<div class="result-grade">${r.released?r.rating:'—'}<small>${r.released?'综合真实评级':'项目已终止'}</small></div>${r.ratings?`<div class="result-ratings">${G.GROUPS.filter(g=>g.id!=='release').map(g=>`<div><small>${g.rating}</small><strong>${r.ratings[g.id].grade}</strong></div>`).join('')}</div>`:''}<div class="result-grid"><div><label>开发时间</label><strong>${r.weeks} 周</strong></div><div><label>累计投入（含买量）</label><strong>${yen(r.cost)}</strong></div><div><label>自然收入</label><strong>${yen(r.organicRevenue)}</strong></div><div><label>买量净回款</label><strong>${yen(r.adRevenue)}</strong></div><div><label>买量投入 / 回款比例</label><strong>${yen(r.adSpend)} / ${r.released?(r.adRate*100).toFixed(1)+'%':'未发售'}</strong></div><div><label>项目结余（含融资）</label><strong class="${r.profit>=0?'teal':'red'}">${yen(r.profit)}</strong></div><div><label>本次制作经验</label><strong>+${r.exp} EXP</strong></div><div><label>累计制作经验</label><strong>${meta.exp} EXP</strong></div></div><p class="result-note">共同完成：${r.team.map(m=>esc(m.name)).join('、')}<br>${r.objectiveOK?'✓ 制作人目标达成，额外 +40 EXP。':'本作未达成制作人目标，保留已获得的制作经验。'}<br>人物与资金每局重置，制作人经验和履历保留。</p><div class="dialog-actions"><button data-action="career" class="btn-ghost">查看作品履历</button><button data-action="setup" class="btn-primary">下一款作品 →</button></div>`,'result');}
  function release(){if(!G.canRelease(run))return;const f=G.forecast(run);showDialog(dialogHeader('READY TO SHIP','让玩家，给出最后的答案。')+`<p class="dialog-desc">资料准备和审核都已达到 100%，可以正式发售。其他工作无最低门槛，未完成部分会影响真实品质与收益。</p><div class="result-grid"><div><label>综合评级认知</label><strong>${esc(f.rating.text)}</strong></div><div><label>当前认知收入区间</label><strong>${yen(f.low)}—${yen(f.high)}</strong></div><div><label>其中买量回款区间</label><strong>${yen(f.ad.low)}—${yen(f.ad.high)}</strong></div><div><label>累计投入</label><strong>${yen(run.spent)}</strong></div></div><p class="quality-note">发售会揭晓四项真实评级和买量回款。宣传不足时，当前判断可能与实际差别很大。自然收入仍有 ±15% 市场波动；买量按发售时真实评级和投入金额结算。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续开发</button><button data-action="confirm-release" class="btn-primary">正式发售 ↗</button></div>`,'release');}
  function help(){showDialog(dialogHeader('STRATEGY HANDBOOK','投入多少，知道多少，何时发售。')+`<div class="manual"><p><strong>五类十三项：</strong>游戏内容（题材、玩法、子主题）；程序构架（开发进度、系统协作、测试）；商业化（广告变现、用户付费、IP衍生）；宣发推广（宣传、买量）；上架（资料准备、审核进度）。在人物卡为每人安排一项工作，专业能力决定产出。</p><p><strong>工作与评级不同：</strong>进度是确定的投入，评级是目前完成度加上本项目固定的大范围随机值。同一完成度也可能是 B 或 S；继续完善可以提高基础值，刷新和反复查看不重掷。</p><p><strong>先获得认知：</strong>四类评级初始为 ?????，宣传进度越高，问号越少。B???? 是粗略判断，可能偏离很远；宣传 100% 揭示当前真实评级。作品继续开发时，评级也会变化，认知范围随之更新。上架状态始终明确。</p><p><strong>宣发是选择：</strong>宣传用于了解作品；买量用于投入资金换取未来回款。安排买量岗位并选择预算后，每周扣费，未安排人手或预算 ¥0 不扣费。买量进度满后，继续安排仍会追加投放；发售前没有回款。</p><p><strong>投放与风险：</strong>综合真实评级按内容 40%、完善度 30%、商业化 20%、推广 10% 计算。净回款比例：D 档 15—40%，C 档 55—90%，B 档 105—140%，A 档 165—230%，S 档 270—380%；若签发行合作，再扣 22% 分成。C、D 档一定亏损，B 档起有回本机会。</p><p><strong>上架是硬条件：</strong>资料准备 100% 后才可推进审核；审核也到 100% 即可发售。其他工作不强制满进度，但提前发售可能得到低评级和亏损。</p><p><strong>人物与成本：</strong>主角加阿策两人开局，伙伴随核心进度加入。转到另一具体工作会磨合一周，即使同属一类；同岗第一人全额，其他人按 45% 协作产能计算。待命照付周薪。</p><p><strong>依赖与构筑：</strong>内容支持开发，开发支持系统协作和测试。系统协作持续偿债，测试持续修问题。内容 60% 可冻结范围，提高实现效率，放弃扩功能；解冻花 ¥180 并返工。蓝图与功能会改变效率、品质潜力和持续成本。</p><p><strong>每一周：</strong>支付工资、维护、工具和买量费用，推进安排，再触发一次事件。无固定周数上限。发售或终止结算经验，新版在途项目独立存档，制作人履历沿用。</p></div><div class="dialog-actions"><button data-action="close" class="btn-primary">回到工作室</button></div>`,'help');}

  function finish(released){const r=G.finish(run,released);if(!r){toast('请先完成当前选择，或检查发售准备。');return;}meta=G.settle(meta,run);close();save();render();result();}
  document.addEventListener('change',e=>{const el=e.target;if(el.id==='ad-budget'&&run){G.setAdBudget(run,Number(el.value));render();return;}if(!el.matches('select[data-member]')||!run)return;const ok=G.assignMember(run,el.dataset.member,el.value);if(!ok)toast('这个岗位暂时不能分配。');render();});
  document.addEventListener('submit',e=>{if(e.target.id!=='setup-form')return;e.preventDefault();const fd=new FormData(e.target),buffs=fd.getAll('buff');let next;try{next=G.newRun({genre:setupGenre,name:fd.get('name'),hard:fd.get('difficulty')==='hard',seed:fd.get('seed'),objective:fd.get('objective'),template:fd.get('template'),heroName:fd.get('heroName'),buffs},meta);}catch(err){$('setup-error').textContent=err.message;return;}if(run&&!run.over){if(run.pendingCards)run.pendingCards=null;if(run.pendingEvent)run.pendingEvent=null;G.finish(run,false);meta=G.settle(meta,run);}run=next;view='game';tab='work';hiddenPrompt=false;close();render();window.scrollTo({top:0,behavior:'smooth'});});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action;
    if(a==='close'){hiddenPrompt=true;close();return;}
    if(a==='audio'){const st=audio.getState();audio.setSettings({muted:!(st.settings?.muted??st.muted)});audio.unlock();return;}
    if(a==='help'){help();return;}
    if(a==='setup'){setup(b.dataset.genre);return;}
    if(a==='setup-genre'){const form=$('setup-form'),name=form?.elements.name.value,normal=form?.elements.difficulty.value,objective=form?.elements.objective.value,template=form?.elements.template.value,heroName=form?.elements.heroName.value,buffs=form?[...form.querySelectorAll('[name=buff]:checked')].map(el=>el.value):[],seed=form?.elements.seed.value;const old=G.GENRES.find(g=>g.id===setupGenre).title;setup(b.dataset.genre);if(name&&name!==old)$('setup-form').elements.name.value=name;if(normal)$('setup-form').elements.difficulty.value=normal;if(objective)$('setup-form').elements.objective.value=objective;if(template)$('setup-form').elements.template.value=template;if(heroName)$('setup-form').elements.heroName.value=heroName;if(seed)$('setup-form').elements.seed.value=seed;$('setup-form').querySelectorAll('[name=buff]').forEach(el=>el.checked=buffs.includes(el.value));return;}
    if(['home','nav','continue','career'].includes(a)){view=a==='nav'?b.dataset.view:a==='continue'?'game':a==='career'?'career':'home';close();hiddenPrompt=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}
    if(a==='result'){result();return;}
    if(a==='tab'){tab=b.dataset.tab;render();return;}
    if(!run||run.over)return;
    if(a==='prompt'){if(run.pendingEvent)showEvent();else if(run.pendingCards)showCards();return;}
    if(a==='card'){if(G.chooseCard(run,b.dataset.id)){close();hiddenPrompt=false;render();}return;}
    if(a==='event'){if(G.resolveEvent(run,Number(b.dataset.index))){close();hiddenPrompt=false;render();}return;}
    if(a==='release'){release();return;}
    if(a==='dismiss'){const m=run.team.find(m=>m.id===b.dataset.id);if(!m||m.kind!=='partner'||busy())return;showDialog(dialogHeader('UNTIL NEXT TIME','与'+esc(m.name)+'暂别？')+`<p class="dialog-desc">支付 ¥100 安置费，之后不再计入${esc(m.name)}的周薪。本项目内不能再次邀请；主角与阿策会继续留下。此操作占用本周管理行动。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续同行</button><button data-action="downsize" data-id="${m.id}">确认暂别 · ¥100</button></div>`,'dismiss');return;}
    if(a==='confirm-release'){finish(true);return;}
    if(a==='confirm-abort'){finish(false);return;}
    if(a==='abort'){showDialog(dialogHeader('PAUSE THIS PROJECT','结束这个项目？')+`<p class="dialog-desc">当前作品不会发售。已完成的 ${run.milestones.length} 个里程碑可保留 ${Math.min(30,run.milestones.length*8)} 点经验，已投入的资金和本局进度不会带到下一作。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续开发</button><button data-action="confirm-abort">结束并结算</button></div>`,'abort');return;}
    if(busy()){toast('请先完成当前事件或蓝图选择。');return;}
    let ok=true;
    if(a==='focus'){run.focus=b.dataset.job;}
    if(a==='budget')ok=G.setAdBudget(run,Number(b.dataset.value));

    if(a==='freeze')ok=G.freeze(run);
    if(a==='pace'){run.pace=b.dataset.pace;}
    if(a==='assign')ok=G.assign(run,b.dataset.job,Number(b.dataset.delta));
    if(a==='hire')ok=G.hire(run,b.dataset.id);
    if(a==='downsize'){ok=G.downsize(run,b.dataset.id);close();}
    if(a==='feature')ok=G.feature(run,b.dataset.id);
    if(a==='cut')ok=G.cutFeature(run,b.dataset.id);
    if(a==='funding'){showDialog(dialogHeader('PUBLISHING PARTNERSHIP','给开发，多一点余地。')+`<p class="dialog-desc">发行商愿意预付 ¥2,200，换取本作发售收入的 22%。这笔资金不增加品质，也不降低开发工作量，每个项目只能签一次。</p><p class="quality-note">发售收入预估将自动按扣除分成后的数值显示。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">先不合作</button><button class="btn-primary" data-action="confirm-funding">接受合作，获得 ¥2,200</button></div>`,'funding');return;}
    if(a==='confirm-funding'){ok=G.funding(run);close();}
    if(a==='advance'){const r=G.advance(run);ok=r.ok;if(!ok)toast(r.reason);hiddenPrompt=false;}
    if(!ok&&a!=='advance')toast('当前条件不满足，操作未执行。');render();
  });
  dialog.addEventListener('cancel',()=>{hiddenPrompt=true;dialogKind='';});
  document.addEventListener('keydown',e=>{if(e.key===' '&&view==='game'&&!dialog.open&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('.next-week')?.click();}});
  // Terminating a project is always visible from its history tab, including an exhausted budget.
  const originalLogs=logs;logs=function(){return originalLogs()+(!run.over?'<div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn-ghost btn-small" data-action="abort">终止当前项目并结算</button></div>':'');};
  if(run&&run.over){meta=G.settle(meta,run);}render();
})();
